function relabelByAudienceCenterOut(dancers) {
  if (dancers.length <= 1) {
    return dancers.map((d2, i2) => ({
      ...d2,
      label: String(i2 + 1),
      colorIndex: modDancerColorIndex(i2)
    }));
  }
  const Y_EPS = 4;
  const indexed = dancers.map((d2, i2) => ({ d: d2, i: i2 }));
  indexed.sort((a2, b2) => b2.d.yPct - a2.d.yPct);
  const rows = [];
  for (const it2 of indexed) {
    const last2 = rows[rows.length - 1];
    if (last2 && Math.abs(last2[0].d.yPct - it2.d.yPct) <= Y_EPS) {
      last2.push(it2);
    } else {
      rows.push([it2]);
    }
  }
  const newLabelByIdx = new Array(dancers.length).fill(0);
  let seq = 1;
  rows.forEach((row, rowIdx) => {
    if (rowIdx === 0) {
      const sorted = [...row].sort((a2, b2) => {
        const da = Math.abs(a2.d.xPct - 50);
        const db = Math.abs(b2.d.xPct - 50);
        if (Math.abs(da - db) > 0.5) return da - db;
        return a2.d.xPct - b2.d.xPct;
      });
      for (const it2 of sorted) newLabelByIdx[it2.i] = seq++;
    } else {
      const sorted = [...row].sort((a2, b2) => a2.d.xPct - b2.d.xPct);
      for (const it2 of sorted) newLabelByIdx[it2.i] = seq++;
    }
  });
  return dancers.map((d2, i2) => ({
    ...d2,
    label: String(newLabelByIdx[i2]),
    colorIndex: modDancerColorIndex(newLabelByIdx[i2] - 1)
  }));
}
